import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 임직원 1인당 허용 인증기기 수. 설정값 출처가 입력에 없어 상수로 둔다.
const MAX_ALLOWED_DEVICES = 3;

const STATUSES = ['신청', '승인', '반려', '해제'];

function idOf(value: string | undefined): string {
  if (value === undefined || !/^[0-9]{1,18}$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '인증기기 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

function reasonOf(data: Record<string, unknown>): string | null {
  const value = data['processReason'];
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > 500) {
    throw new ApiError(400, 'VALIDATION_FAILED', '처리 사유는 500자 이내의 글자로 입력하세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03703Controller {
  @Get('/auth-devices')
  async listAuthDevices(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const params: Record<string, unknown> = {};
    const conditions: string[] = [];
    const employeeId = query['employeeId'];
    if (employeeId !== undefined && employeeId !== null && employeeId !== '') {
      if (!/^[0-9]{1,18}$/.test(String(employeeId))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID는 숫자여야 합니다.');
      }
      conditions.push('employee_id = CAST(:employeeId AS bigint)');
      params['employeeId'] = String(employeeId);
    }
    const status = query['status'];
    if (status !== undefined && status !== null && status !== '') {
      if (!STATUSES.includes(String(status))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
      }
      conditions.push('status = :status');
      params['status'] = String(status);
    }
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    const where = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
    return transaction(async (db) => {
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM auth_device ${where}`,
        params,
      );
      const items = await db.query(
        `SELECT auth_device_id AS "authDeviceId",
                employee_id AS "employeeId",
                device_identifier AS "deviceIdentifier",
                device_name AS "deviceName",
                status AS "status"
           FROM auth_device
           ${where}
          ORDER BY auth_device_id DESC
          LIMIT :limit OFFSET :offset`,
        { ...params, limit: size, offset: pageRaw * size },
      );
      return {
        items,
        page: pageRaw,
        size,
        total: Number(totalRows[0]['total']),
      };
    });
  }

  @Post('/auth-devices/:authDeviceId/approve')
  @HttpCode(200)
  async approveAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id AS "employeeId", status AS "status"
           FROM auth_device
          WHERE auth_device_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'AUTH_DEVICE_NOT_FOUND', '인증기기를 찾을 수 없습니다.');
      }
      const device = found[0];
      if (String(device['status']) !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 처리된 인증기기입니다.');
      }
      if (String(device['employeeId']) === user.id) {
        throw new ApiError(403, 'FORBIDDEN', '본인이 신청한 인증기기는 처리할 수 없습니다.');
      }
      const counted = await db.query(
        `SELECT COUNT(*) AS "count"
           FROM auth_device
          WHERE employee_id = CAST(:employeeId AS bigint)
            AND status = '승인'`,
        { employeeId: String(device['employeeId']) },
      );
      if (Number(counted[0]['count']) >= MAX_ALLOWED_DEVICES) {
        throw new ApiError(422, 'ALLOWED_DEVICE_COUNT_EXCEEDED', '허용 인증기기 수를 초과하여 승인할 수 없습니다.');
      }
      const updated = await db.query(
        `UPDATE auth_device
            SET status = '승인',
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
      RETURNING auth_device_id AS "authDeviceId", status AS "status"`,
        { id, userId: user.id },
      );
      return updated[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/reject')
  @HttpCode(200)
  async rejectAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    const data = checks.inputOf(req.body);
    const reason = reasonOf(data);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id AS "employeeId", status AS "status"
           FROM auth_device
          WHERE auth_device_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'AUTH_DEVICE_NOT_FOUND', '인증기기를 찾을 수 없습니다.');
      }
      const device = found[0];
      if (String(device['status']) !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 처리된 인증기기입니다.');
      }
      if (String(device['employeeId']) === user.id) {
        throw new ApiError(403, 'FORBIDDEN', '본인이 신청한 인증기기는 처리할 수 없습니다.');
      }
      const updated = await db.query(
        `UPDATE auth_device
            SET status = '반려',
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                process_reason = :reason,
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
      RETURNING auth_device_id AS "authDeviceId", status AS "status"`,
        { id, userId: user.id, reason },
      );
      return updated[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/release')
  @HttpCode(200)
  async releaseAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    const data = checks.inputOf(req.body);
    const reason = reasonOf(data);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id AS "employeeId", status AS "status"
           FROM auth_device
          WHERE auth_device_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'AUTH_DEVICE_NOT_FOUND', '인증기기를 찾을 수 없습니다.');
      }
      const device = found[0];
      if (String(device['status']) !== '승인') {
        throw new ApiError(409, 'AUTH_DEVICE_STATUS_MISMATCH', '승인 상태의 인증기기만 해제할 수 있습니다.');
      }
      if (String(device['employeeId']) === user.id) {
        throw new ApiError(403, 'FORBIDDEN', '본인이 신청한 인증기기는 처리할 수 없습니다.');
      }
      // 가정: 해제 처리자도 현재 사용자로 기록한다.
      const updated = await db.query(
        `UPDATE auth_device
            SET status = '해제',
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                process_reason = :reason,
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
      RETURNING auth_device_id AS "authDeviceId", status AS "status"`,
        { id, userId: user.id, reason },
      );
      return updated[0];
    });
  }
}

