import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

type Kind = 'approve' | 'reject' | 'release';

const KIND_TEXT: Record<Kind, string> = {
  approve: '승인',
  reject: '반려',
  release: '사용 해제',
};

export default function FnSfr03703Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<{ employeeId: number | string; status: string }>({ employeeId: '', status: '' });
  const [applied, setApplied] = useState<{ employeeId: number | string; status: string }>({ employeeId: '', status: '' });
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [action, setAction] = useState<{ kind: Kind; row: Row } | null>(null);
  const [reason, setReason] = useState('');

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/auth-devices', role, undefined, {
        employeeId: applied.employeeId,
        status: applied.status,
        page,
        size: SIZE,
      }),
    [role, applied, page],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/auth-devices', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );

  const reloadAll = () => {
    list.reload();
    pending.reload();
  };

  const openAction = (kind: Kind, row: Row) => {
    setReason('');
    setAction({ kind, row });
  };

  const submitAction = async () => {
    if (!action) {
      return;
    }
    const body: Row = action.kind === 'approve' ? {} : { processReason: reason };
    await call('POST', `/auth-devices/${action.row.authDeviceId}/${action.kind}`, role, body);
    notify(`인증기기를 ${KIND_TEXT[action.kind]}했습니다.`);
    setAction(null);
    reloadAll();
  };

  const buttons = (row: Row) => (
    <span>
      {row.status === '신청' && (
        <button type="button" onClick={(e) => { e.stopPropagation(); openAction('approve', row); }}>
          승인
        </button>
      )}
      {row.status === '신청' && (
        <button type="button" onClick={(e) => { e.stopPropagation(); openAction('reject', row); }}>
          반려
        </button>
      )}
      {row.status === '승인' && (
        <button type="button" onClick={(e) => { e.stopPropagation(); openAction('release', row); }}>
          사용 해제
        </button>
      )}
    </span>
  );

  const columns = [
    { key: 'authDeviceId', label: '인증기기 ID' },
    { key: 'employeeId', label: '임직원', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'deviceName', label: '기기 명칭' },
    { key: 'deviceIdentifier', label: '인증기기 식별값' },
    { key: 'status', label: '상태', render: (r: Row) => <Badge value={r.status} /> },
    { key: 'action', label: '처리', render: buttons },
  ];

  const pendingColumns = [
    { key: 'deviceName', label: '기기 명칭' },
    { key: 'employeeId', label: '임직원', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'action', label: '처리', render: buttons },
  ];

  return (
    <div className="bento">
      <section className="box span-6">
        <h2>조회 건수</h2>
        <strong><Num value={list.data?.total ?? 0} /></strong>
      </section>
      <section className="box span-6">
        <h2>승인 대기</h2>
        <strong><Num value={pending.data?.total ?? 0} /></strong>
      </section>

      <section className="box span-8">
        <h2>인증기기 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(draft);
          }}
          onReset={() => {
            const empty = { employeeId: '', status: '' };
            setDraft(empty);
            setApplied(empty);
            setPage(0);
          }}
        >
          <Field label="임직원 ID">
            <LookupSelect
              table="employee"
              role={role}
              value={draft.employeeId}
              onChange={(v) => setDraft({ ...draft, employeeId: v })}
              placeholder="전체"
            />
          </Field>
          <Field label="상태">
            <Select
              value={draft.status}
              onChange={(v) => setDraft({ ...draft, status: v })}
              options={[['신청', '신청'], ['승인', '승인'], ['반려', '반려'], ['해제', '해제']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={list.data?.total} />
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          columns={columns}
          rows={list.data?.items ?? []}
          onRowClick={(r) => setDetail(r)}
          empty="인증기기가 없습니다."
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기 목록</h2>
        {pending.error && <ErrorText text={pending.error} />}
        <DataTable
          columns={pendingColumns}
          rows={pending.data?.items ?? []}
          onRowClick={(r) => setDetail(r)}
          empty="처리 대기 중인 기기가 없습니다."
        />
      </section>

      {detail && (
        <Drawer title="인증기기 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['인증기기 ID', String(detail.authDeviceId)],
              ['임직원 ID', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['기기 명칭', String(detail.deviceName ?? '')],
              ['인증기기 식별값', String(detail.deviceIdentifier ?? '')],
              ['상태', <Badge value={detail.status} />],
            ]}
          />
        </Drawer>
      )}

      {action && (
        <Drawer title={`인증기기 ${KIND_TEXT[action.kind]}`} onClose={() => setAction(null)}>
          <Pairs
            items={[
              ['기기 명칭', String(action.row.deviceName ?? '')],
              ['임직원 ID', <RefName table="employee" role={role} value={action.row.employeeId} />],
              ['상태', <Badge value={action.row.status} />],
            ]}
          />
          <Form
            onSubmit={submitAction}
            submit={KIND_TEXT[action.kind]}
            danger={action.kind !== 'approve'}
          >
            {action.kind !== 'approve' && (
              <Field label="처리 사유" wide hint="500자 이내">
                <TextInput value={reason} onChange={setReason} multiline />
              </Field>
            )}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
